<?php $cfg=require __DIR__.'/config.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$host=$_POST['host'];$db=$_POST['db'];$user=$_POST['dbuser'];$pass=$_POST['dbpass'];$adminEmail=$_POST['admin_email'];$adminPass=$_POST['admin_pass'];try{$pdo2=new PDO("mysql:host=$host;charset=utf8mb4",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$pdo2->exec("CREATE DATABASE IF NOT EXISTS `".preg_replace('/[^a-zA-Z0-9_]/','',$db)."` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");$pdo2->exec("USE `".preg_replace('/[^a-zA-Z0-9_]/','',$db)."`");$sql=file_get_contents(__DIR__.'/database.sql');$pdo2->exec($sql);$st=$pdo2->prepare("INSERT INTO users(name,email,password_hash,role,status) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE role='superadmin', status='active'");$st->execute(['مدیر اصلی',$adminEmail,password_hash($adminPass,PASSWORD_DEFAULT),'superadmin','active']);$template=file_get_contents(__DIR__.'/config.example.php');$template=str_replace("'127.0.0.1'",var_export($host,true),$template);$template=str_replace("'shopx'",var_export($db,true),$template);$template=str_replace("'root'",var_export($user,true),$template);$template=str_replace("'pass' => ''","'pass' => ".var_export($pass,true),$template);file_put_contents(__DIR__.'/config.php',$template);$msg='نصب انجام شد. install.php را حذف کنید و سپس وارد شوید.';}catch(Throwable $e){$msg='خطا: '.$e->getMessage();}}?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/css/style.css"><title>نصب SHOPX</title></head><body><main class="container"><div class="panel" style="max-width:650px;margin:40px auto"><h1>نصب SHOPX</h1><?php if($msg): ?><div class="alert ok"><?=htmlspecialchars($msg)?></div><?php endif; ?><form method="post"><div class="form-grid"><div class="field"><label>DB Host</label><input name="host" value="127.0.0.1" required></div><div class="field"><label>DB Name</label><input name="db" value="shopx" required></div><div class="field"><label>DB User</label><input name="dbuser" value="root" required></div><div class="field"><label>DB Password</label><input type="password" name="dbpass"></div><div class="field"><label>ایمیل مدیر</label><input type="email" name="admin_email" required></div><div class="field"><label>رمز مدیر</label><input type="password" name="admin_pass" minlength="8" required></div></div><button class="btn">شروع نصب</button></form></div></main></body></html>
